7	import {
8	  type SandboxManager,
9	  type SandboxRequest,
10	  type SandboxedCommand,
11	} from '../../services/sandboxManager.js';
12	import {
13	  sanitizeEnvironment,
14	  getSecureSanitizationConfig,
15	  type EnvironmentSanitizationConfig,
16	} from '../../services/environmentSanitization.js';
17	import { buildSeatbeltArgs } from './seatbeltArgsBuilder.js';
18	
19	/**
20	 * Options for configuring the MacOsSandboxManager.
21	 */
22	export interface MacOsSandboxOptions {
23	  /** The primary workspace path to allow access to within the sandbox. */
24	  workspace: string;
25	  /** Additional paths to allow access to within the sandbox. */
26	  allowedPaths?: string[];
27	  /** Whether network access is allowed. */
28	  networkAccess?: boolean;
29	  /** Optional base sanitization config. */
30	  sanitizationConfig?: EnvironmentSanitizationConfig;
31	}
32	
33	/**
34	 * A SandboxManager implementation for macOS that uses Seatbelt.
35	 */
36	export class MacOsSandboxManager implements SandboxManager {
37	  constructor(private readonly options: MacOsSandboxOptions) {}
38	
39	  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
40	    const sanitizationConfig = getSecureSanitizationConfig(
41	      req.config?.sanitizationConfig,
42	      this.options.sanitizationConfig,
43	    );
44	
45	    const sanitizedEnv = sanitizeEnvironment(req.env, sanitizationConfig);
46	
47	    const sandboxArgs = buildSeatbeltArgs({
48	      workspace: this.options.workspace,
49	      allowedPaths: this.options.allowedPaths,
50	      networkAccess: this.options.networkAccess,
51	    });
52	
53	    return {
54	      program: '/usr/bin/sandbox-exec',
55	      args: [...sandboxArgs, '--', req.command, ...req.args],
