22	  async readTextFile(filePath: string): Promise<string> {
23	    const prepared = await this.sandboxManager.prepareCommand({
24	      command: '__read',
25	      args: [filePath],
26	      cwd: this.cwd,
27	      env: process.env,
28	    });
29	
30	    return new Promise((resolve, reject) => {
31	      // Direct spawn is necessary here for streaming large file contents.
32	
33	      const child = spawn(prepared.program, prepared.args, {
34	        cwd: this.cwd,
35	        env: prepared.env,
36	      });
37	
38	      let output = '';
39	      let error = '';
40	
41	      child.stdout?.on('data', (data) => {
42	        output += data.toString();
