50	        if (code === 0) {
51	          resolve(output);
52	        } else {
53	          reject(
54	            new Error(
55	              `Sandbox Error: read_file failed for '${filePath}'. Exit code ${code}. ${error ? 'Details: ' + error : ''}`,
